import {
  Toc as TocPrimitive,
  type UseTocProps,
  useToc as useTocPrimitive,
  useTocContext as useTocContextPrimitive,
} from '@ark-ui/solid/toc';
import { clsx } from 'clsx';
import type { ComponentProps, JSX } from 'solid-js';
import { mergeProps, splitProps } from 'solid-js';
import styles from './Toc.module.css';

const railStep = 12;
const railBridge = 6;

// Depths 2 to 4 get their own rail column; deeper headings stay on the last one.
const getRailX = (depth: number) => Math.min(Math.max(depth - 2, 0), 2) * railStep + 0.5;

const useToc = (props: UseTocProps) => useTocPrimitive(mergeProps({ autoScroll: false }, props));

const useTocContext = useTocContextPrimitive;

function Toc(props: ComponentProps<typeof TocPrimitive.Root>) {
  const [local, others] = splitProps(props, ['autoScroll', 'class']);

  return (
    <TocPrimitive.Root
      autoScroll={local.autoScroll ?? false}
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="toc-root"
    />
  );
}

function TocRootProvider(props: ComponentProps<typeof TocPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TocPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="toc-root-provider"
    />
  );
}

function TocContent(props: ComponentProps<typeof TocPrimitive.Content>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TocPrimitive.Content
      class={clsx(styles.content, local.class)}
      {...others}
      data-slot="toc-content"
    />
  );
}

function TocNav(props: ComponentProps<typeof TocPrimitive.Nav>) {
  const [local, others] = splitProps(props, ['class']);

  return <TocPrimitive.Nav class={clsx(styles.nav, local.class)} {...others} data-slot="toc-nav" />;
}

function TocTitle(props: ComponentProps<typeof TocPrimitive.Title>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TocPrimitive.Title class={clsx(styles.title, local.class)} {...others} data-slot="toc-title" />
  );
}

function TocList(props: ComponentProps<typeof TocPrimitive.List>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TocPrimitive.List class={clsx(styles.list, local.class)} {...others} data-slot="toc-list" />
  );
}

function TocItem(props: ComponentProps<typeof TocPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TocPrimitive.Item class={clsx(styles.item, local.class)} {...others} data-slot="toc-item" />
  );
}

function TocLink(props: ComponentProps<typeof TocPrimitive.Link>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TocPrimitive.Link class={clsx(styles.link, local.class)} {...others} data-slot="toc-link" />
  );
}

function TocIndicator(props: ComponentProps<typeof TocPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TocPrimitive.Indicator
      class={clsx(styles.indicator, local.class)}
      {...others}
      data-slot="toc-indicator"
    />
  );
}

type TocRailProps = ComponentProps<'svg'> & {
  depth: number;
  previousDepth?: number;
  nextDepth?: number;
};

const nonScalingStrokeProps = {
  'vector-effect': 'non-scaling-stroke',
} as const;

function TocRail(props: TocRailProps) {
  const [local, others] = splitProps(props, [
    'class',
    'depth',
    'nextDepth',
    'previousDepth',
    'style',
  ]);
  const x = () => getRailX(local.depth);
  const previousX = () => getRailX(local.previousDepth ?? local.depth);
  const nextX = () => getRailX(local.nextDepth ?? local.depth);
  const hasTurn = () => previousX() !== x();
  const style = (): JSX.CSSProperties | string => {
    const width = `${Math.max(previousX(), x(), nextX()) + 1.5}px`;
    // Cross the list gap to the next rail, and its bridge too when the line continues.
    const height = `calc(100% + ${nextX() === x() ? railBridge : 0}px + var(--moduix-spacing-0-5))`;

    if (typeof local.style === 'string') {
      return `width:${width};height:${height};${local.style}`;
    }

    return { width, height, ...local.style };
  };

  return (
    <svg
      aria-hidden="true"
      class={clsx(styles.rail, local.class)}
      style={style()}
      {...others}
      data-slot="toc-rail"
    >
      {hasTurn() && (
        <path
          d={`M ${previousX()} 0 C ${previousX()} 8 ${x()} 4 ${x()} ${railBridge * 2}`}
          fill="none"
          {...nonScalingStrokeProps}
          stroke="currentColor"
        />
      )}
      <line
        x1={x()}
        y1={hasTurn() ? railBridge * 2 : railBridge}
        x2={x()}
        y2="100%"
        {...nonScalingStrokeProps}
        stroke="currentColor"
      />
    </svg>
  );
}

const TocContext = TocPrimitive.Context;

export {
  Toc,
  TocContext,
  TocContent,
  TocIndicator,
  TocItem,
  TocLink,
  TocList,
  TocNav,
  TocRail,
  TocRootProvider,
  TocTitle,
  useToc,
  useTocContext,
};

export type {
  TocActiveChangeDetails,
  TocContentProps,
  TocContextProps,
  TocIndicatorProps,
  TocItemData,
  TocItemProps,
  TocLinkProps,
  TocListProps,
  TocNavProps,
  TocRootProps,
  TocRootProviderProps,
  TocTitleProps,
  UseTocContext,
  UseTocProps,
  UseTocReturn,
} from '@ark-ui/solid/toc';
export type { TocRailProps };

@layer moduix.components {
  .root {
    display: grid;
    width: 100%;
    min-width: 0;
    grid-template-columns: minmax(0, 1fr) minmax(12rem, 16rem);
    gap: var(--moduix-spacing-6);
    color: var(--moduix-color-foreground);
    /* Read Ark measurements here: parents of the list, such as Collapsible, redefine --top and --height. */
    --_toc-indicator-top: var(--top);
    --_toc-indicator-height: var(--height);

    &:has(.nav[data-placement='left']) {
      grid-template-columns: minmax(12rem, 16rem) minmax(0, 1fr);
    }

    @media (width < 48rem) {
      &,
      &:has(.nav[data-placement='left']) {
        grid-template-columns: minmax(0, 1fr);
      }
    }
  }

  .content {
    min-width: 0;
  }

  .nav {
    position: sticky;
    top: var(--moduix-spacing-4);
    align-self: start;
    max-height: calc(100dvh - 2rem);
    overflow: auto;
    padding: var(--moduix-spacing-4);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-color-card);
    color: var(--moduix-color-card-foreground);

    /* The content takes the next free cell, so only the nav needs explicit placement. */
    &[data-placement='left'] {
      grid-row: 1;
      grid-column: 1;

      @media (width < 48rem) {
        grid-area: auto;
      }
    }
  }

  .title {
    margin: 0 0 var(--moduix-spacing-2);
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-sm);
  }

  .list {
    position: relative;
    display: grid;
    gap: var(--moduix-spacing-0-5);
    margin: 0;
    padding-inline-start: var(--moduix-spacing-1);
    list-style: none;

    &:has(.indicator)::before {
      position: absolute;
      top: var(--moduix-spacing-0-5);
      bottom: var(--moduix-spacing-0-5);
      inset-inline-start: 0;
      width: var(--moduix-border-width-md);
      border-radius: var(--moduix-radius-full);
      background-color: var(--moduix-color-border);
      content: '';
      pointer-events: none;
    }
  }

  .item {
    min-width: 0;
  }

  .link {
    position: relative;
    display: block;
    padding-block: var(--moduix-spacing-1);
    padding-inline-end: var(--moduix-spacing-1);
    padding-inline-start: calc(
      var(--moduix-spacing-1) + var(--moduix-border-width-md) + var(--moduix-spacing-2) +
        max(0px, calc((var(--depth) - 2) * var(--moduix-spacing-2)))
    );
    /* Clip only horizontally so TocRail can reach the neighbouring items. */
    overflow-x: clip;
    border-radius: var(--moduix-radius-sm);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    text-decoration: none;
    text-overflow: ellipsis;
    white-space: nowrap;
    outline: none;
    transition: color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        color: var(--moduix-color-foreground);
      }
    }

    &:focus-visible {
      box-shadow: 0 0 0 var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        var(--moduix-color-ring);
    }

    &[data-active] {
      color: var(--moduix-color-foreground);
      font-weight: var(--moduix-weight-medium);

      .rail {
        color: var(--moduix-color-muted-foreground);
        opacity: 0.7;
        translate: 0 var(--moduix-spacing-0-5);
      }
    }
  }

  .indicator {
    z-index: 1;
    top: calc(var(--_toc-indicator-top) + var(--moduix-spacing-0-5));
    inset-inline-start: 0;
    width: var(--moduix-border-width-md);
    height: calc(var(--_toc-indicator-height) - var(--moduix-spacing-1));
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-color-muted-foreground);
    opacity: 0.7;
    pointer-events: none;
    transition:
      top var(--moduix-transition-default),
      height var(--moduix-transition-default);
  }

  .rail {
    position: absolute;
    top: calc(-1 * var(--moduix-spacing-1-5));
    inset-inline-start: 0;
    overflow: visible;
    color: var(--moduix-color-border);
    pointer-events: none;

    & :is(line, path) {
      stroke-width: var(--moduix-border-width-sm);
    }
  }
}
